import type { SiteKey } from "./types";

export type ExpansionSite = Exclude<SiteKey, "style">;

export type FamilyEditorialBrief = {
  job: string;
  dimensions: [string, string, string, string];
  setup: string;
  ownership: string;
  skip: string;
};

function brief(
  job: string,
  dimensions: [string, string, string, string],
  setup: string,
  ownership: string,
  skip: string,
): FamilyEditorialBrief {
  return { job, dimensions, setup, ownership, skip };
}

